// JarvisLive.js — the /jarvis route (the folder name is legacy, not the URL).
//
// A public, no-sign-in page where a visitor talks to Jarvis: the terminal AI
// coding assistant from github.com/Laxman824/JarvisAssistant, running for real
// as a serverless function. Not a mockup and not a recording — the same
// agent loop, the same tools, answering out of its own source code.
//
// It exists because CAMSCode — the enterprise version of this, and the strongest
// project on the site — can never be demonstrated. This one can.
//
// SHAPE OF THE PAGE (revised 2026-08-08). It is a chat application: a fixed
// viewport, one scrolling transcript, a composer pinned to the floor. Each
// turn is user question → the trace that answered it → the answer. The earlier
// build put four paragraphs of framing above a single page-level terminal, and
// the framing pushed the actual product below the fold on arrival while the
// terminal ended up orphaned in the middle of long answers.
//
// So the framing now lives *inside* the transcript as its first block: fully
// present on arrival, scrolled away for good the moment a conversation starts.
// The long version is behind a disclosure — a recruiter who wants the why can
// open it; everyone else gets to the thing itself immediately.
//
// The trace is per-turn and inline, expanded on the newest turn and collapsed
// on older ones. Collapsing everything by default (as a normal chat app would)
// would hide the one thing this page exists to show.
//
// The badge in the composer always states which transport actually served the
// answer. That honesty is a feature: a "live" badge over a canned response
// would be a lie, and the whole point of the page is that this one is real.
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import Header from "../../../components/header/Header";
import MdLite from "../../../utils/MdLite";
import { forcedTransport, health, runTurn } from "./jarvisClient";
import "./JarvisLive.css";

const SUGGESTIONS = [
  {
    label: "How does your failover work?",
    prompt:
      "How does your provider failover work? Look at _FAILOVER_CHAINS in agent/loop.py and explain in two sentences.",
  },
  {
    label: "Show me your structure",
    prompt:
      "Show me your project structure, then describe in one sentence what the agent/ folder is responsible for.",
  },
  {
    label: "How do you stay safe?",
    prompt:
      "How does your approval gate stop you from sending an email without permission? Read agent/approval.py.",
  },
  {
    label: "How many tools do you have?",
    prompt:
      "How many tools do you actually have, and how does the tool router decide which ones to offer each turn?",
  },
];

// Reduced motion is handled entirely in CSS (@media prefers-reduced-motion).

// Shown dimmed before the first question, explicitly labelled as an example.
// The trace is the reason the page exists and it used to sit empty on arrival,
// which sold nothing — a visitor could not tell what they were being invited
// to watch. Labelling matters: a canned trace passed off as live would be
// exactly the lie the honesty badge exists to prevent.
const SAMPLE_REASONING =
  "I need the definition, not a mention of it. Reading all of loop.py will " +
  "blow the read cap — search for the symbol first, then re-read just the " +
  "range around it.";

const SAMPLE_TRACE = [
  {
    kind: "tool",
    step: 1,
    ok: true,
    state: "done",
    call: 'search_files(pattern="_FAILOVER_CHAINS")',
    summary: "14 matches in 6 files",
    ms: 820,
  },
  {
    kind: "tool",
    step: 2,
    ok: true,
    state: "done",
    call: 'read_file(path="agent/loop.py")',
    summary: "6,144 chars · truncated at the read cap",
    ms: 410,
  },
  {
    kind: "tool",
    step: 3,
    ok: true,
    state: "done",
    call: 'read_file(path="agent/loop.py", start_line=1760, end_line=1850)',
    summary: "90 lines · 3,204 chars",
    ms: 380,
  },
];

// ============================================
// CALL RENDERING
// ============================================
// The literal invocation the model produced, tinted like source because that
// is what it is. Which file it chose is the demo; making the arguments legible
// at a glance is most of what makes that readable.
const CALL_TOKEN = /("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\b(?:True|False|None)\b|\b\d+(?:\.\d+)?\b|[A-Za-z_]\w*(?=\s*=))/g;

function tokenClass(token) {
  if (token[0] === '"' || token[0] === "'") return "jv-t-str";
  if (/^(True|False|None)$/.test(token)) return "jv-t-kw";
  if (/^\d/.test(token)) return "jv-t-num";
  return "jv-t-arg";
}

function CallCode({ text }) {
  const match = /^([A-Za-z_]\w*)\(([\s\S]*)\)$/.exec(text || "");
  if (!match) return <>{text}</>;
  const [, name, args] = match;
  return (
    <>
      <span className="jv-t-fn">{name}</span>
      <span className="jv-t-punc">(</span>
      {args.split(CALL_TOKEN).map((part, i) =>
        i % 2 === 1 ? (
          <span className={tokenClass(part)} key={i}>
            {part}
          </span>
        ) : (
          <span className="jv-t-punc" key={i}>
            {part}
          </span>
        )
      )}
      <span className="jv-t-punc">)</span>
    </>
  );
}

function formatMs(ms) {
  return ms < 1000 ? `${Math.round(ms)}ms` : `${(ms / 1000).toFixed(1)}s`;
}

// ============================================
// TRACE — one turn's machinery, inline
// ============================================
// Sits between the question and the answer, in the order it happened: the
// model reasons, calls tools, then speaks. Collapsed it is a single summary
// row; opened it is the terminal.
function Trace({ lines, thinking, meta, busy, open, onToggle, sample }) {
  const tools = lines.filter((line) => line.kind === "tool");
  const done = tools.filter((t) => t.state === "done").length;
  const failed = lines.some((line) => line.kind === "err");

  let label;
  if (sample) label = "Example — ask a question to run a real one";
  else if (busy && tools.length === 0) label = "Working";
  else if (busy) label = `Step ${done + 1} of ${tools.length}`;
  // Before the no-tools case: a turn that died on the quota gate also made no
  // tool calls, and calling that "answered directly" is simply untrue.
  else if (failed) label = "Stopped before answering";
  else if (tools.length === 0) label = "Answered directly — no tools needed";
  else label = `Completed ${tools.length} step${tools.length === 1 ? "" : "s"}`;

  return (
    <div className={`jv-trace ${sample ? "jv-trace-sample" : ""}`}>
      <button
        type="button"
        className="jv-trace-head"
        onClick={onToggle}
        aria-expanded={open}
      >
        <span className={`jv-chev ${open ? "jv-chev-open" : ""}`}>›</span>
        <span className="jv-trace-label">{label}</span>
        {busy && <span className="jv-dots" />}
        {meta && <span className="jv-trace-meta">{meta}</span>}
      </button>

      {open && (
        <div className="jv-term">
          <div className="jv-term-bar">
            <span className="jv-tdot jv-tdot-r" />
            <span className="jv-tdot jv-tdot-y" />
            <span className="jv-tdot jv-tdot-g" />
            <span className="jv-term-title">
              jarvis@vercel&nbsp;·&nbsp;~/JarvisAssistant
            </span>
          </div>

          <div className="jv-term-body">
            {/* Reasoning first: it is what the model does *before* choosing a
                tool, so showing it above the calls matches the actual order. */}
            {thinking && (
              <div className="jv-reason">
                <div className="jv-reason-label">reasoning</div>
                <div className="jv-reason-text">{thinking}</div>
              </div>
            )}

            {lines.map((line, i) => {
              if (line.kind === "tool") {
                return (
                  <div className="jv-tool-block" key={i}>
                    <div className="jv-tool">
                      <span className="jv-tool-step">{line.step}</span>
                      {/* The real call, arguments and all. "It read a file" is
                          trivia; "it chose to read *this* file" is the demo. */}
                      <code className="jv-tool-call">
                        <CallCode text={line.call || `${line.name}(…)`} />
                      </code>
                      {line.ms != null && (
                        <span className="jv-tool-ms">{formatMs(line.ms)}</span>
                      )}
                      <span
                        className={`jv-tool-state jv-tool-${
                          line.state === "running"
                            ? "running"
                            : line.ok
                            ? "ok"
                            : "err"
                        }`}
                      >
                        {line.state === "running" ? "⋯" : line.ok ? "✓" : "✗"}
                      </span>
                    </div>
                    {line.summary && (
                      <div className="jv-tool-summary">{line.summary}</div>
                    )}
                  </div>
                );
              }
              return (
                <div className={`jv-tline jv-tline-${line.kind}`} key={i}>
                  {line.text}
                </div>
              );
            })}

            {busy && (
              <div className="jv-tline jv-tline-dim">
                working
                <span className="jv-dots" />
              </div>
            )}

            {meta && <div className="jv-tline jv-tline-ok">{meta}</div>}
          </div>
        </div>
      )}
    </div>
  );
}

// ============================================
// INTRO — the first block in the transcript
// ============================================
// Scrolls away like any other message once a conversation starts. The short
// version is always visible because without it the page is one more portfolio
// chatbot; the long version is one click away because four paragraphs of
// preamble above a chat box is a worse first impression than the chat box.
function Intro({ expanded, onToggle }) {
  return (
    <div className="jv-intro">
      <p className="jv-eyebrow">The one I can actually show you</p>
      <h1 className="jv-title">
        Ask my AI coding assistant about{" "}
        <span className="jv-title-dim">its own source code.</span>
      </h1>
      <p className="jv-lede">
        <strong>Jarvis</strong> is running below for real — six LLM providers,
        ~100 tools, its own agent loop, sandboxed to read-only access over its
        own repository. Every question shows you the reasoning, the exact tool
        calls and what came back.
      </p>

      <button type="button" className="jv-why" onClick={onToggle}>
        <span className={`jv-chev ${expanded ? "jv-chev-open" : ""}`}>›</span>
        Why this page exists
      </button>

      {expanded && (
        <div className="jv-why-body">
          <p className="jv-lede">
            At CAMS I built <strong>CAMSCode</strong> — an agentic coding
            assistant that turns specs into working applications, running
            entirely inside their network so regulated financial data never
            leaves it. It is the strongest thing I have built, and I can never
            show it to you: it lives behind a corporate boundary, so you would
            have to take my word for it.
          </p>
          <p className="jv-lede">
            Jarvis is the same system built personally and open source. So
            instead of describing an agent loop, I can hand you one.
          </p>
          <div className="jv-intro-links">
            <a className="jv-link" href="/projects/camscode">
              The CAMSCode case study →
            </a>
            <a
              className="jv-link"
              href="https://github.com/Laxman824/JarvisAssistant"
              target="_blank"
              rel="noreferrer"
            >
              Jarvis source on GitHub →
            </a>
          </div>
        </div>
      )}

      {/* What to look for — otherwise the trace is just noise to a
          non-engineer, and the mechanism is the entire point. */}
      <ul className="jv-watch">
        <li>
          <span>reasoning</span> the model deciding what it needs
        </li>
        <li>
          <span>tool calls</span> the exact arguments it chose
        </li>
        <li>
          <span>results</span> what came back, and how it adapts
        </li>
        <li>
          <span>failover</span> a dead provider caught mid-turn
        </li>
      </ul>
    </div>
  );
}

// ============================================
// MAIN
// ============================================
const JarvisLive = ({ theme, setTheme }) => {
  const [input, setInput] = useState("");
  // {role:'user',content} | {role:'assistant',content,lines,thinking,meta}
  const [turns, setTurns] = useState([]);
  const [streaming, setStreaming] = useState("");
  const [lines, setLines] = useState([]);
  const [busy, setBusy] = useState(false);
  const [thinking, setThinking] = useState("");
  const [meta, setMeta] = useState("");
  const [provider, setProvider] = useState(null);
  const [quota, setQuota] = useState(null);
  const [transport, setTransport] = useState(null); // null = unknown yet
  const [note, setNote] = useState("");
  const [whyOpen, setWhyOpen] = useState(false);
  // Trace indices the visitor has collapsed, plus every turn but the newest.
  const [collapsed, setCollapsed] = useState(() => new Set());

  const abortRef = useRef(null);
  const inputRef = useRef(null);
  const threadRef = useRef(null);

  const forced = useMemo(() => forcedTransport(), []);

  // Probe so the badge is honest before the first question, rather than
  // claiming "live" and discovering otherwise mid-answer.
  //
  // Twice, with a longer budget than the client's default. The API is a
  // serverless function that scales to zero, so the *first* visitor of the
  // hour pays a cold start — and a single short probe was declaring the demo
  // "offline" on exactly the load where a visitor forms their impression,
  // while the thing was in fact perfectly healthy.
  useEffect(() => {
    let cancelled = false;
    if (forced === "replay") {
      setTransport("replay");
      return undefined;
    }

    (async () => {
      for (let attempt = 0; attempt < 2; attempt += 1) {
        const info = await health(9000);
        if (cancelled) return;
        if (info && info.ok) {
          setTransport("live");
          setProvider(info.defaultProvider);
          return;
        }
      }
      if (!cancelled) setTransport("down");
    })();

    return () => {
      cancelled = true;
    };
  }, [forced]);

  useEffect(() => () => abortRef.current?.abort(), []);

  // Follow the newest content — but only once a conversation exists. On the
  // first paint there is nothing to follow, and scrolling to the bottom
  // regardless threw the visitor past the framing they had not read yet.
  //
  // The thread is its own scroll container, so this never moves the page, and
  // it sidesteps the site-wide `overflow: clip` that makes scrollIntoView a
  // no-op.
  const conversing = turns.length > 0 || busy;
  useEffect(() => {
    if (!conversing) return;
    const el = threadRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [conversing, turns, streaming, lines, busy, thinking]);

  // Chrome restores a scroll container's offset across reloads, which on this
  // page means arriving at the bottom of a transcript that no longer exists.
  useEffect(() => {
    const el = threadRef.current;
    if (el) el.scrollTop = 0;
  }, []);

  const status = useMemo(() => {
    if (busy) return { kind: "live", label: "● running" };
    if (transport === "live") return { kind: "live", label: "● live" };
    if (transport === "replay") return { kind: "replay", label: "▸ replay" };
    if (transport === "down") return { kind: "down", label: "○ offline" };
    return { kind: "idle", label: "○ connecting" };
  }, [busy, transport]);

  const honestyLine = useMemo(() => {
    if (transport === "live") {
      return "The real Jarvis, running serverless — read-only tools, sandboxed to its own source.";
    }
    if (transport === "down") {
      return "Jarvis isn't reachable right now. The code is on GitHub in the meantime.";
    }
    if (transport === "replay") {
      return "Replaying a recorded session — not a live model call.";
    }
    return "Checking whether Jarvis is awake…";
  }, [transport]);

  const ask = useCallback(
    async (prompt) => {
      const text = (prompt || "").trim();
      if (!text || busy) return;

      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      setInput("");
      setNote("");
      setMeta("");
      setLines([]);
      setStreaming("");
      setThinking("");
      setBusy(true);

      const history = turns
        .filter((t) => t.role === "user" || t.content)
        .slice(-6)
        .map((t) => ({ role: t.role, content: t.content }));

      // Collapse every existing trace: only the turn about to run stays open.
      setCollapsed((prev) => {
        const next = new Set(prev);
        turns.forEach((turn, i) => {
          if (turn.role === "assistant") next.add(i);
        });
        return next;
      });
      setTurns((prev) => [...prev, { role: "user", content: text }]);

      // Where this turn's answer will land: `turns` is the pre-push value, so
      // the user message takes turns.length and the assistant the slot after.
      const assistantAt = turns.length + 1;

      // The trace is accumulated locally as well as in state: the completed
      // turn is assembled after `await`, where the state closure is stale.
      let answer = "";
      let reasoning = "";
      let metaText = "";
      const trace = [];
      const indexOf = {};
      const startedAt = {};

      await runTurn({
        prompt: text,
        history,
        signal: controller.signal,
        onEvent: (event) => {
          switch (event.type) {
            case "status":
              setProvider(event.model || event.provider);
              setTransport(event.transport);
              if (event.quota) setQuota(event.quota);
              break;

            case "text":
              answer += event.delta;
              setStreaming(answer);
              break;

            case "thinking":
              // Reasoning tokens the terminal REPL prints in grey and throws
              // away. Recovered by wrapping the provider client, because
              // showing how the model reasons its way to a tool call is the
              // whole reason this page exists.
              reasoning += event.delta;
              setThinking(reasoning);
              break;

            case "tool_start":
              startedAt[event.id] = performance.now();
              indexOf[event.id] = trace.length;
              trace.push({
                kind: "tool",
                step: trace.filter((l) => l.kind === "tool").length + 1,
                icon: event.icon,
                verb: event.verb,
                name: event.name,
                detail: event.detail,
                state: "running",
              });
              setLines([...trace]);
              break;

            case "tool_args": {
              const at = indexOf[event.id];
              if (at == null || !trace[at]) break;
              trace[at] = { ...trace[at], call: event.call };
              setLines([...trace]);
              break;
            }

            case "tool_summary": {
              const at = indexOf[event.id];
              if (at == null || !trace[at]) break;
              trace[at] = { ...trace[at], summary: event.summary };
              setLines([...trace]);
              break;
            }

            case "tool_result": {
              const at = indexOf[event.id];
              if (at == null || !trace[at]) break;
              const began = startedAt[event.id];
              trace[at] = {
                ...trace[at],
                state: "done",
                ok: event.ok,
                ms: began != null ? performance.now() - began : null,
              };
              setLines([...trace]);
              break;
            }

            case "failover":
              // Worth surfacing rather than hiding: watching one provider die
              // and another pick the turn up is the clearest demonstration of
              // the failover chain the project is built around.
              trace.push({
                kind: "warn",
                text: `⚠ ${event.from} unavailable — failing over to ${event.to}`,
              });
              setLines([...trace]);
              break;

            case "done":
              metaText = `${event.toolCalls} tool${
                event.toolCalls === 1 ? "" : "s"
              } · ${(event.ms / 1000).toFixed(1)}s · ${event.inTokens} in / ${
                event.outTokens
              } out`;
              setMeta(metaText);
              break;

            case "error":
              if (event.code === "quota") {
                setNote(
                  "You've used today's free questions. The live demo is rate-limited so the free-tier keys survive the day — come back tomorrow, or read the source on GitHub."
                );
              } else if (event.code === "busy") {
                setNote(
                  "Jarvis is answering someone else. Try again in a moment."
                );
              } else {
                setNote(event.message || "Something went wrong.");
              }
              trace.push({
                kind: "err",
                text: `✗ ${event.message || event.code}`,
              });
              setLines([...trace]);
              break;

            default:
              break;
          }
        },
      });

      setBusy(false);
      setStreaming("");
      setLines([]);
      setThinking("");
      setMeta("");
      setTurns((prev) => [
        ...prev,
        {
          role: "assistant",
          content: answer,
          lines: trace,
          thinking: reasoning,
          meta: metaText,
        },
      ]);

      // Expanded while it runs, collapsed once it lands: you watch the loop
      // work, then you read the answer without scrolling past the machinery
      // that produced it. One click on the summary row brings it back.
      //
      // Unless the turn produced no answer — then the trace is the only thing
      // there is to show, and hiding it would leave a blank turn.
      if (answer.trim()) {
        setCollapsed((prev) => new Set(prev).add(assistantAt));
      }
    },
    [busy, turns]
  );

  const toggleTrace = useCallback((index) => {
    setCollapsed((prev) => {
      const next = new Set(prev);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      return next;
    });
  }, []);

  const onKeyDown = (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      ask(input);
    }
  };

  const disabled = busy || transport === "down";
  const started = conversing;

  return (
    <div
      className="jv-page"
      data-theme={theme?.name}
      style={{
        "--jv-body": theme?.body,
        "--jv-text": theme?.text,
        "--jv-sub": theme?.secondaryText,
        "--jv-accent": theme?.accentColor,
      }}
    >
      <Header theme={theme} setTheme={setTheme} />

      <div className="jv-shell">
        {/* ---------------- TRANSCRIPT ---------------- */}
        <div className="jv-thread" ref={threadRef}>
          <div className="jv-thread-inner">
            <Intro expanded={whyOpen} onToggle={() => setWhyOpen((v) => !v)} />

            {/* Before the first question, the anatomy of a trace — otherwise
                the page's whole promise is an empty box. */}
            {!started && (
              <div className="jv-turn jv-turn-assistant">
                <Trace
                  sample
                  open
                  onToggle={() => {}}
                  lines={SAMPLE_TRACE}
                  thinking={SAMPLE_REASONING}
                  meta="3 tools · 12.4s · 8,510 in / 431 out"
                  busy={false}
                />
              </div>
            )}

            {turns.map((turn, i) =>
              turn.role === "user" ? (
                <div className="jv-turn jv-turn-user" key={i}>
                  <p className="jv-user-text">{turn.content}</p>
                </div>
              ) : (
                <div className="jv-turn jv-turn-assistant" key={i}>
                  {(turn.lines.length > 0 || turn.thinking) && (
                    <Trace
                      lines={turn.lines}
                      thinking={turn.thinking}
                      meta={turn.meta}
                      busy={false}
                      open={!collapsed.has(i)}
                      onToggle={() => toggleTrace(i)}
                    />
                  )}
                  {turn.content.trim() ? (
                    <MdLite text={turn.content} />
                  ) : turn.lines.some((l) => l.kind === "err") ? null : (
                    /* It happens: the model spends its tool budget navigating
                       and stops with nothing said. Saying so beats rendering
                       a trace followed by silence. Skipped when the turn
                       errored — the banner below already gives the reason,
                       and blaming the tool budget for a quota stop is wrong. */
                    <p className="jv-noanswer">
                      Jarvis ran out of tool calls before it answered. The trace
                      above shows where they went — a narrower question usually
                      gets there.
                    </p>
                  )}
                </div>
              )
            )}

            {/* The turn in flight. Its trace is always open — watching it
                happen is the payoff. */}
            {busy && (
              <div className="jv-turn jv-turn-assistant">
                <Trace
                  lines={lines}
                  thinking={thinking}
                  meta={meta}
                  busy
                  open
                  onToggle={() => {}}
                />
                {streaming && (
                  <>
                    <MdLite text={streaming} />
                    <span className="jv-caret" />
                  </>
                )}
              </div>
            )}

            {note && <p className="jv-note">{note}</p>}
          </div>
        </div>

        {/* ---------------- COMPOSER (pinned) ---------------- */}
        <div className="jv-dock">
          <div className="jv-dock-inner">
            {/* Only before the first question: once there is a conversation,
                a row of canned prompts under the box is clutter. */}
            {!started && (
              <div className="jv-chips">
                {SUGGESTIONS.map((s) => (
                  <button
                    key={s.label}
                    type="button"
                    className="jv-chip"
                    disabled={disabled}
                    onClick={() => ask(s.prompt)}
                  >
                    {s.label}
                  </button>
                ))}
              </div>
            )}

            <div className={`jv-composer ${busy ? "jv-composer-busy" : ""}`}>
              <textarea
                ref={inputRef}
                className="jv-input"
                placeholder={
                  transport === "down"
                    ? "Jarvis is offline right now…"
                    : started
                    ? "Ask a follow-up…"
                    : "Ask Jarvis about its own code…"
                }
                value={input}
                rows={1}
                maxLength={500}
                disabled={disabled}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={onKeyDown}
              />

              <div className="jv-composer-row">
                <span className="jv-pill jv-pill-static">read-only</span>
                {/* The model is real, and it changes: a failover mid-turn
                    visibly swaps it. Worth showing for that reason alone. */}
                <span
                  className="jv-model"
                  title="The provider and model serving this turn"
                >
                  <span className="jv-model-dot" />
                  {provider || "connecting…"}
                </span>
                <button
                  type="button"
                  className="jv-send"
                  disabled={disabled || !input.trim()}
                  onClick={() => ask(input)}
                >
                  {busy ? "⋯" : "↑"}
                </button>
              </div>
            </div>

            {/* Session bar — the demo runs on free-tier keys, so the budget is
                real and worth being upfront about. Spent questions read as
                filled pips, so the allowance is legible without arithmetic. */}
            <div className="jv-session">
              <span className={`jv-session-state jv-badge-${status.kind}`}>
                {status.label}
              </span>
              <span className="jv-session-note">{honestyLine}</span>
              <span className="jv-session-quota">
                <span className="jv-pips" aria-hidden="true">
                  {Array.from({ length: quota ? quota.limit : 3 }).map(
                    (_, i) => (
                      <i
                        key={i}
                        className={
                          i < (quota ? quota.remaining : 3) ? "jv-pip-on" : ""
                        }
                      />
                    )
                  )}
                </span>
                {quota
                  ? `${quota.remaining} of ${quota.limit} left today`
                  : "3 free questions a day"}
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default JarvisLive;
